parameters.jsCode:
// Format fraud alert report
const raw = $input.first().json;
const alert = raw.data || raw;
const payload = alert.payload || {};
const fraudReport = alert.fraud_report || {};

return [{
  json: {
    alert_type: 'FRAUD_REJECTED',
    device_id: payload.device_id || 'unknown',
    utr: payload.utr || 'unknown',
    amount: payload.amount || 0,
    merchant_id: payload.merchant_id || 'unknown',
    fraud_score: fraudReport.overall_score || 0,
    flags: fraudReport.flags || ['FRAUD_DETECTED'],
    layers: fraudReport.layers || {},
    timestamp: new Date().toISOString()
  }
}];

